"# Анализ зависимостей fill_energy_passport.py\n\n$filePath = \"C:\\eaip\\tools\\fill_energy_passport.py\"\n\nWrite-Host \"=== АНАЛИЗ СТРУКТУРЫ ФАЙЛА ===\" -ForegroundColor Yellow\n\n# 1. Подсчет строк и функций\n$lines = Get-Content $filePath\n$totalLines = $lines.Count\n\n# Считаем функции\n$functionCount = 0\n$functionNames = @()\nfor ($i = 0; $i -lt $lines.Count; $i++) {\n    if ($lines[$i] -match '^def (\w+)') {\n        $functionCount++\n        $functionNames += $matches[1]\n    }\n}\n\n# Считаем классы\n$classCount = 0\n$classNames = @()\nfor ($i = 0; $i -lt $lines.Count; $i++) {\n    if ($lines[$i] -match '^class (\w+)') {\n        $classCount++\n        $classNames += $matches[1]\n    }\n}\n\nWrite-Host \"Общая статистика:\" -ForegroundColor Cyan\nWrite-Host \"  Всего строк: $totalLines\"\nWrite-Host \"  Функций: $functionCount\"\nWrite-Host \"  Классов: $classCount\"\n\n# 2. Анализ импортов\nWrite-Host \"`n=== ИМПОРТЫ ===\" -ForegroundColor Yellow\n$imports = @()\nfor ($i = 0; $i -lt 100; $i++) {  # Первые 100 строк обычно содержат импорты\n    if ($lines[$i] -match '^(import|from) ') {\n        $imports += $lines[$i]\n    }\n}\nWrite-Host \"Всего импортов: $($imports.Count)\"\n$imports | ForEach-Object { Write-Host \"  $_\" }\n\n# 3. Поиск основных групп функций\nWrite-Host \"`n=== ГРУППИРОВКА ФУНКЦИЙ ===\" -ForegroundColor Yellow\n\n# Паттерны для группировки\n$patterns = @{\n    'Excel' = @('excel', 'ws\\.', 'cell\\.', 'workbook', 'sheet', 'openpyxl', 'xlsx', 'xls')\n    'Data' = @('data', 'process', 'transform', 'convert', 'parse', 'extract')\n    'Validation' = @('valid', 'check', 'verify', 'assert', 'is_.*')\n    'Template' = @('template', 'метин', 'шаблон', 'pattern')\n    'Utility' = @('util', 'helper', '_', 'get_', 'set_', 'find_', 'create_')\n}\n\n$functionGroups = @{}\nforeach ($func in $functionNames) {\n    $group = 'Other'\n    foreach ($key in $patterns.Keys) {\n        foreach ($pattern in $patterns[$key]) {\n            if ($func -match $pattern -or $func.ToLower() -match $pattern) {\n                $group = $key\n                break\n            }\n        }\n        if ($group -ne 'Other') { break }\n    }\n    \n    if (-not $functionGroups.ContainsKey($group)) {\n        $functionGroups[$group] = @()\n    }\n    $functionGroups[$group] += $func\n}\n\nforeach ($group in $functionGroups.Keys | Sort-Object) {\n    Write-Host (\"`n{0} ({1} функций):\" -f $group, $functionGroups[$group].Count) -ForegroundColor Cyan\n    $functionGroups[$group] | Sort-Object | ForEach-Object { Write-Host \"  $_\" }\n}\n\n# 4. Поиск самых больших функций\nWrite-Host \"`n=== САМЫЕ БОЛЬШИЕ ФУНКЦИИ ===\" -ForegroundColor Yellow\n\n$functionSizes = @{}\n$currentFunction = $null\n$functionStart = 0\n\nfor ($i = 0; $i -lt $lines.Count; $i++) {\n    if ($lines[$i] -match '^def (\w+)') {\n        if ($currentFunction) {\n            $size = $i - $functionStart\n            $functionSizes[$currentFunction] = $size\n        }\n        $currentFunction = $matches[1]\n        $functionStart = $i\n    }\n}\n\n# Последняя функция\nif ($currentFunction) {\n    $size = $lines.Count - $functionStart\n    $functionSizes[$currentFunction] = $size\n}\n\n# Топ-10 самых больших функций\n$topFunctions = $functionSizes.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 10\n\nforeach ($func in $topFunctions) {\n    Write-Host (\"{0}: {1} строк\" -f $func.Key, $func.Value)\n}\n\n# 5. Рекомендации по разделению\nWrite-Host \"`n=== РЕКОМЕНДАЦИИ ===\" -ForegroundColor Green\n\nWrite-Host \"1. Первый кандидат для выноса: Excel-операции\"\nWrite-Host \"   Функций: $($functionGroups['Excel'].Count)\"\nWrite-Host \"   Примеры: $($functionGroups['Excel'][0..4] -join ', ')...\"\n\nWrite-Host \"`n2. Второй кандидат: Вспомогательные функции\"\nWrite-Host \"   Функций: $($functionGroups['Utility'].Count)\"\n\nWrite-Host \"`n3. Третий кандидат: Валидация\"\nWrite-Host \"   Функций: $($functionGroups['Validation'].Count)\"\n\nWrite-Host \"`n4. Структура после рефакторинга:\"\nWrite-Host \"   fill_energy_passport/\"\nWrite-Host \"   ├── __init__.py\"\nWrite-Host \"   ├── excel_operations.py\"\nWrite-Host \"   ├── data_processor.py\"\nWrite-Host \"   ├── validators.py\"\nWrite-Host \"   ├── template_manager.py\"\nWrite-Host \"   └── utils.py\""